// The tombstone serve law (tombstone-lifecycle 3.2): the DEFAULT item listing
// drops deleted rows in BOTH branches (the scored walk and the sort=path
// opt-out — one seam, the shared allFilteredItems walk), an explicit
// ?status=deleted stays the operator's audit window, libraryEpisodes
// inherits the law (a vanished episode feeds no per-series fact and stamps
// no Watched off its dead ledger row), and the item-detail GET is the serve
// boundary — a tombstoned row answers the same 404 a missing row does while
// the write routes keep accepting the id. All over the REAL router wiring
// and a real store.

// tombstoneRecsItem soft-deletes a seeded item row the way the sweep does
// (scan sweepItems): the row's OWN document passed back through PutItem,
// status flipped, the bytes untouched.
func tombstoneRecsItem(t *testing.T, st *store.Store, it store.Item) {
	t.Helper()
	it.Status = statusDeleted
	if err := st.PutItem(context.Background(), it); err != nil {
		t.Fatalf("tombstone %s: %v", it.ID, err)
	}
}

// TestListItemsExcludesDeletedByDefault pins the listing default: an
// absent/empty ?status= serves active rows only — on the scored default AND
// the sort=path opt-out (which reads through the same walk and cuts its page
// in Go, preserving id order and full pages) — while ?status=deleted keeps
// exact-match semantics (the audit window serves exactly the dead rows).
func TestListItemsExcludesDeletedByDefault(t *testing.T) {
	h, st, lib := newRecsAPI(t)

	ctx := context.Background()
	// id order: itm_t1 < itm_t2 < itm_t3 — sort=path assertions ride it.
	// The scored branch omits zero-score rows (scoredServe's floor), so the
	// scored assertion rides POSITIVE-score seeds: both the live and the
	// dead film carry progress — without the serve law the dead film would
	// score and serve, so the subtest can fail on the red reality.
	liveA := seedRecsItem(t, st, lib, "itm_t1", "aaa.mkv", map[string]any{}, time.Time{})
	liveB := seedRecsItem(t, st, lib, "itm_t2", "bbb.mkv", map[string]any{}, time.Time{})
	dead := seedRecsItem(t, st, lib, "itm_t3", "ccc.mkv", map[string]any{}, time.Time{})
	if _, err := st.PutProgress(ctx, liveB.ID, 300, access.System()); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}
	if _, err := st.PutProgress(ctx, dead.ID, 900, access.System()); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}
	tombstoneRecsItem(t, st, dead)

	t.Run("scored_default_drops_dead", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(lib), "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		lr := decodeItems(t, resp)
		// The dead film's progress never serves: score-desc order puts the
		// live films in progress order and the tombstoned row is gone (its
		// 900s progress would otherwise outrank liveB's 300s).
		wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }), liveB.ID, liveA.ID)
	})

	t.Run("sort_path_drops_dead_keeps_id_order", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(lib)+"&sort=path", "", adminToken)
		defer resp.Body.Close()
		lr := decodeItems(t, resp)
		wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }), liveA.ID, liveB.ID)
		for _, d := range lr.Items {
			if d.RecScore != 0 {
				t.Fatalf("sort=path computed scores (%v on %s) — the opt-out must serve unscored", d.RecScore, d.ID)
			}
		}
	})

	t.Run("sort_path_window_cuts_live_rows_only", func(t *testing.T) {
		// The Go-side page cut over the walked set: offset skips LIVE rows
		// (a dropped dead row never hollows a page).
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(lib)+"&sort=path&limit=1&offset=1", "", adminToken)
		defer resp.Body.Close()
		lr := decodeItems(t, resp)
		wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }), liveB.ID)
	})

	t.Run("explicit_status_deleted_is_the_audit_window", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(lib)+"&status=deleted", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		lr := decodeItems(t, resp)
		wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }), dead.ID)
	})
}

// TestLibraryEpisodesExcludesDeleted is the Q10 inheritance pin: the series
// listing's per-series episode facts ride the same walk, so a tombstoned
// episode feeds no fact — the series stamps no Watched off the dead row's
// ledger entry (the item detail 404s; the series list agrees), live facts
// still stamp, and the dead episode never surfaces on the episodes route.
func TestLibraryEpisodesExcludesDeleted(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	sr := seedRecsSeries(t, st, lib, "show", recsSeriesDoc("show"))
	deadEp := seedRecsItem(t, st, lib, "itm_de1", "show/e1.mkv", recsEpisodeDoc("show", "E1"), time.Time{})
	if err := st.InsertWatched(ctx, deadEp.ID, lib, "", time.Now().UTC(), access.System()); err != nil {
		t.Fatalf("InsertWatched: %v", err)
	}
	tombstoneRecsItem(t, st, deadEp)

	t.Run("dead_episode_stamps_nothing", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(lib), "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		rows := decodeSeriesList(t, resp)
		if len(rows) != 1 {
			t.Fatalf("served %d series, want 1", len(rows))
		}
		if rows[0].Watched {
			t.Fatalf("series %s stamped Watched off a tombstoned episode's ledger row", rows[0].ID)
		}
	})

	liveEp := seedRecsItem(t, st, lib, "itm_de2", "show/e2.mkv", recsEpisodeDoc("show", "E2"), time.Time{})
	if err := st.InsertWatched(ctx, liveEp.ID, lib, "", time.Now().UTC(), access.System()); err != nil {
		t.Fatalf("InsertWatched: %v", err)
	}

	t.Run("live_facts_still_stamp", func(t *testing.T) {
		// Every SERVING episode is ledgered → the all-episodes law stamps.
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(lib), "", adminToken)
		defer resp.Body.Close()
		rows := decodeSeriesList(t, resp)
		if len(rows) != 1 || !rows[0].Watched {
			t.Fatalf("served %v, want the one series stamped Watched off its live episode", rows)
		}
	})

	t.Run("dead_episode_absent_from_episodes_route", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series/"+sr.ID+"/episodes", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		lr := decodeItems(t, resp)
		wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }), liveEp.ID)
	})
}

// TestGetItemDeletedAnswersNotFound pins the serve boundary: the item-detail
// GET answers the SAME 404 not_found for a tombstoned row as for a missing
// one (gone, not forbidden), while the write routes keep accepting the
// tombstoned id (the re-seed path rides them).
func TestGetItemDeletedAnswersNotFound(t *testing.T) {
	h, st, lib := newRecsAPI(t)

	it := seedRecsItem(t, st, lib, "itm_g1", "gone.mkv", map[string]any{}, time.Time{})

	resp := doRequest(t, h, http.MethodGet, "/api/v1/items/"+it.ID, "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("live item status = %d, want 200", resp.StatusCode)
	}

	tombstoneRecsItem(t, st, it)

	resp = doRequest(t, h, http.MethodGet, "/api/v1/items/"+it.ID, "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusNotFound {
		t.Fatalf("tombstoned item status = %d, want 404", resp.StatusCode)
	}
	eb := decodeError(t, resp)
	if eb.Error.Code != "not_found" {
		t.Fatalf("tombstoned item error code = %q, want not_found", eb.Error.Code)
	}

	// A never-seen id answers the same shape — status and error code — as a
	// tombstone (gone, not forbidden; the message carries the requested id
	// in both cases).
	resp = doRequest(t, h, http.MethodGet, "/api/v1/items/itm_never", "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusNotFound {
		t.Fatalf("missing item status = %d, want 404", resp.StatusCode)
	}
	missing := decodeError(t, resp)
	if missing.Error.Code != eb.Error.Code {
		t.Fatalf("missing item code %q differs from tombstoned code %q", missing.Error.Code, eb.Error.Code)
	}

	// The write route keeps accepting the tombstoned id (PUT /progress/{id}).
	resp = doRequest(t, h, http.MethodPut, "/api/v1/progress/"+it.ID, `{"position_seconds":120}`, adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("PUT progress on tombstoned id status = %d, want 200 (write routes stay functional)", resp.StatusCode)
	}
}
